using Interoper.Generator;

namespace Interoper.Tool;

/// <summary>What <see cref="Bindings.Write"/> changed, relative to the folder, with the OS's separators.</summary>
public sealed record BindingChanges(IReadOnlyList<string> Written, IReadOnlyList<string> Deleted);

/// <summary>Writes generated files to a folder (design §5): the CLI's and the golden slice's one code path.</summary>
public static class Bindings
{
    /// <summary>The first line of every file the generator writes (design §4).</summary>
    public const string Header = "// <auto-generated/>";

    /// <summary>The CLI's own folder in the output, the IR cache's: never scanned for stale files.</summary>
    public const string CacheFolder = ".interoper";

    /// <summary>
    /// Writes each file whose text differs (so an unchanged one keeps its timestamp), then deletes the generated files
    /// (<c>.cs</c> or <c>.js</c> starting with <see cref="Header"/>) this run didn't produce, and the folders that leaves
    /// empty. Anything else in the folder, such as a hand-written partial, is kept.
    /// </summary>
    public static BindingChanges Write(string folder, IEnumerable<GeneratedFile> files)
    {
        folder = Path.TrimEndingDirectorySeparator(Path.GetFullPath(folder));
        var written = new List<string>();
        var produced = new HashSet<string>(StringComparer.Ordinal);
        foreach (var file in files)
        {
            var path = Path.GetFullPath(Path.Combine(folder, file.Path));
            produced.Add(path);
            if (!File.Exists(path) || File.ReadAllText(path) != file.Text)
            {
                Directory.CreateDirectory(Path.GetDirectoryName(path)!);
                File.WriteAllText(path, file.Text);
                written.Add(Path.GetRelativePath(folder, path));
            }
        }

        var deleted = new List<string>();
        if (Directory.Exists(folder))
        {
            var cache = Path.Combine(folder, CacheFolder) + Path.DirectorySeparatorChar;
            var stale = Directory.EnumerateFiles(folder, "*", SearchOption.AllDirectories)
                .Where(f => !f.StartsWith(cache, StringComparison.Ordinal) && !produced.Contains(f) && IsGenerated(f))
                .Order(StringComparer.Ordinal)
                .ToList();
            foreach (var file in stale)
            {
                File.Delete(file);
                deleted.Add(Path.GetRelativePath(folder, file));
                for (var dir = Path.GetDirectoryName(file)!; dir.Length > folder.Length && !Directory.EnumerateFileSystemEntries(dir).Any(); dir = Path.GetDirectoryName(dir)!)
                {
                    Directory.Delete(dir);
                }
            }
        }
        return new(written, deleted);
    }

    private static bool IsGenerated(string path)
    {
        if (!path.EndsWith(".cs", StringComparison.Ordinal) && !path.EndsWith(".js", StringComparison.Ordinal))
        {
            return false;
        }
        using var reader = new StreamReader(path);
        return reader.ReadLine() == Header;
    }
}
